class Container:
    def __init__(self):
        self.instances = {}
    def resolve(self, name):
        if name not in self.instances:
            self.instances[name] = self.factories[name](self)
        return self.instances[name]

container = Container()
container.factories = {
    "catalog": lambda c: Catalog(c.resolve("search")),
    "search": lambda c: Search(c.resolve("catalog")),
}
